import java.util.ArrayList;
import java.util.List;

public class Pizza {
    private final String size;
    private final List<String> toppings;
    private final boolean extraCheese;

    private Pizza(Builder b) {
        size = b.size;
        toppings = List.copyOf(b.toppings);
        extraCheese = b.extraCheese;
    }

    public static Builder builder(String size) {
        if (!List.of("small", "medium", "large").contains(size)) throw new IllegalArgumentException("unknown size: " + size);
        return new Builder(size);
    }

    public String size() { return size; }
    public List<String> toppings() { return toppings; }
    public boolean extraCheese() { return extraCheese; }

    public int price() {
        int base = switch (size) {
            case "small" -> 800;
            case "medium" -> 1000;
            default -> 1200;
        };
        return base + 150 * toppings.size() + (extraCheese ? 100 : 0);
    }

    @Override
    public String toString() {
        return size + ": " + (toppings.isEmpty() ? "plain" : String.join(", ", toppings)) + (extraCheese ? " + extra cheese" : "");
    }

    public static class Builder {
        private final String size;
        private final List<String> toppings = new ArrayList<>();
        private boolean extraCheese;

        private Builder(String size) { this.size = size; }

        public Builder topping(String t) {
            if (!toppings.contains(t)) toppings.add(t);
            return this;
        }

        public Builder extraCheese() {
            extraCheese = true;
            return this;
        }

        public Pizza build() { return new Pizza(this); }
    }
}

unitTests:
test("building", () -> {
    Pizza p = Pizza.builder("medium").topping("ham").topping("olives").topping("ham").extraCheese().build();
    checkEq(p.toString(), "medium: ham, olives + extra cheese");
    checkEq(p.toppings(), java.util.List.of("ham", "olives"));
    checkEq(p.price(), 1000 + 300 + 100);
    checkEq(Pizza.builder("small").build().toString(), "small: plain");
    checkEq(Pizza.builder("large").topping("x").build().price(), 1350);
});

test("rules", () -> {
    checkThrows(IllegalArgumentException.class, () -> Pizza.builder("huge"));
    Pizza p = Pizza.builder("small").topping("corn").build();
    checkThrows(UnsupportedOperationException.class, () -> p.toppings().add("ham"));
});

test("the builder does not change finished pizzas", () -> {
    Pizza.Builder b = Pizza.builder("small").topping("a");
    Pizza first = b.build();
    b.topping("b");
    checkEq(first.toppings(), java.util.List.of("a"));
});

